def _credit_points(grade, credits):
    points = {'A': 4.0, 'B': 3.0, 'C': 2.0, 'D': 1.0, 'F': 0.0}
    return points.get(grade, 0.0) * credits


def _totals(courses):
    total_points = 0.0
    total_credits = 0
    for grade, credits in courses:
        total_points += _credit_points(grade, credits)
        total_credits += 1
    return total_points, total_credits


def gpa(courses):
    total_points, total_credits = _totals(courses)
    if total_credits == 0:
        return 0.0
    return round(total_points / total_credits, 2)
